	@Test
	void saveReadUpdateDeleteAndListQueries() throws Exception {
		SailRepository storageRepository = new SailRepository(new MemoryStore());
		storageRepository.init();
		QueryStorage storage = new QueryStorage(storageRepository);
		ByteArrayOutputStream buffer = new ByteArrayOutputStream();
		TupleResultBuilder builder = new TupleResultBuilder(new WorkbenchTupleResultWriter(buffer), VF);
		String repositoryReference = "urn:test:repository";
		String originalQuery = "select * where { ?s ?p ?o }";
		String updatedQuery = "select * where { ?s ?p ?o . filter(?s = ?s) }";

		storage.saveQuery(repositoryReference, "team-query", "alice", false, QueryLanguage.SPARQL, originalQuery,
				true, 10, 5);

		assertThat(storage.askExists(repositoryReference, "team-query", "alice")).isTrue();
		IRI savedQuery = storage.selectSavedQuery(repositoryReference, "alice", "team-query");
		assertThat(storage.getQueryText(repositoryReference, "alice", "team-query")).isEqualTo(originalQuery);
		assertThat(storage.canChange(savedQuery, "alice")).isTrue();
		assertThat(storage.canChange(savedQuery, "bob")).isFalse();
		assertThat(storage.canRead(savedQuery, "bob")).isFalse();

		storage.updateQuery(savedQuery, "alice", true, QueryLanguage.SPARQL, updatedQuery, false, 20, 0);

		assertThat(storage.canRead(savedQuery, "bob")).isTrue();
		storage.selectSavedQueries(repositoryReference, "bob", builder);
		builder.end();
		String xml = buffer.toString(StandardCharsets.UTF_8);
		assertThat(xml)
				.contains("team-query")
				.contains(updatedQuery)
				.contains("SPARQL")
				.contains("20");

		storage.deleteQuery(savedQuery, "alice");
		assertThat(storage.askExists(repositoryReference, "team-query", "alice")).isFalse();
		assertThatThrownBy(() -> storage.selectSavedQuery(repositoryReference, "alice", "team-query"))
				.isInstanceOf(BadRequestException.class)
				.hasMessageContaining("Could not find query entry in storage.");
		assertThatThrownBy(() -> storage.getQueryText(repositoryReference, "alice", "team-query"))
				.isInstanceOf(BadRequestException.class)
				.hasMessageContaining("Could not find query entry in storage.");

		storage.shutdown();
	}

	@Test
	void canReadTreatsCraftedUserNameAsData() throws Exception {
		SailRepository storageRepository = new SailRepository(new MemoryStore());
		storageRepository.init();
		QueryStorage storage = new QueryStorage(storageRepository);
		try {
			storage.saveQuery("urn:test:repository", "private-query", "alice", false, QueryLanguage.SPARQL,
					"select * where { ?s ?p ?o }", false, 10, 0);
			IRI savedQuery = storage.selectSavedQuery("urn:test:repository", "alice", "private-query");
			String craftedUser = "mallory\" || true || \"";

			assertThat(storage.canRead(savedQuery, craftedUser)).isFalse();
			assertThatThrownBy(
					() -> storage.selectSavedQuery("urn:test:repository", craftedUser, "private-query"))
							.isInstanceOf(BadRequestException.class);

			ByteArrayOutputStream buffer = new ByteArrayOutputStream();
			TupleResultBuilder builder = new TupleResultBuilder(new WorkbenchTupleResultWriter(buffer), VF);
			storage.selectSavedQueries("urn:test:repository", craftedUser, builder);
			builder.end();
			assertThat(buffer.toString(StandardCharsets.UTF_8)).doesNotContain("private-query");
		} finally {
			storage.shutdown();
		}
	}

	@Test
	void storesAndMatchesSparqlSyntaxAsBoundValues() throws Exception {
		SailRepository storageRepository = new SailRepository(new MemoryStore());
		storageRepository.init();
		QueryStorage storage = new QueryStorage(storageRepository);
		String repositoryReference = "urn:test:repository> } UNION { ?s ?p ?o";
		String owner = "alice\" || true || \"\n\\雪";
		String queryName = "name\" . } UNION { ?s ?p ?o #\n\\雪";
		String originalQuery = "select '''single''' \"\"\"double\"\"\" where { ?s ?p \"\\n#{}雪\" }";
		String updatedQuery = "ask { bind(\"'\\\\\"#{}雪\" as ?value) }";
		try {
			storage.saveQuery(repositoryReference, queryName, owner, false, QueryLanguage.SPARQL, originalQuery,
					true, 20, 7);

			assertThat(storage.askExists(repositoryReference, queryName, owner)).isTrue();
			assertThat(storage.askExists(repositoryReference, "missing\" || true || \"", owner)).isFalse();
			IRI savedQuery = storage.selectSavedQuery(repositoryReference, owner, queryName);
			assertThat(storage.getQueryText(repositoryReference, owner, queryName)).isEqualTo(originalQuery);
			assertThat(storage.canRead(savedQuery, owner)).isTrue();

			storage.updateQuery(savedQuery, "mallory\" || true || \"", true, QueryLanguage.SPARQL,
					"attacker update", false, 10, 0);
			assertThat(storage.getQueryText(repositoryReference, owner, queryName)).isEqualTo(originalQuery);

			storage.deleteQuery(savedQuery, "mallory\" || true || \"");
			assertThat(storage.askExists(repositoryReference, queryName, owner)).isTrue();

			storage.updateQuery(savedQuery, owner, true, QueryLanguage.SPARQL, updatedQuery, false, 50, 0);
			assertThat(storage.getQueryText(repositoryReference, owner, queryName)).isEqualTo(updatedQuery);
			storage.deleteQuery(savedQuery, owner);
			assertThat(storage.askExists(repositoryReference, queryName, owner)).isFalse();
		} finally {
			storage.shutdown();
		}
	}

	@Test
	void saveQueryRejectsIllegalInputs() throws Exception {
		SailRepository storageRepository = new SailRepository(new MemoryStore());
		storageRepository.init();
		QueryStorage storage = new QueryStorage(storageRepository);

		assertThatThrownBy(() -> storage.saveQuery("urn:test:repository", "bad", "alice", false,
				new QueryLanguage("SERQL"),
				"select * where { ?s ?p ?o }", true, 10, 0))
						.isInstanceOf(RepositoryException.class)
						.hasMessageContaining("May only save SPARQL queries");
		assertThatThrownBy(() -> storage.saveQuery("urn:test:repository", "bad", "alice", false, QueryLanguage.SPARQL,
				"select * where { ?s ?p ?o }", true, 13, 0))
						.isInstanceOf(RepositoryException.class)
						.hasMessageContaining("Illegal value for rows per page");
		assertThatThrownBy(() -> storage.saveQuery("urn:test:repository", "bad", "alice", false, QueryLanguage.SPARQL,
				"select * where { ?s ?p ?o }", true, 10, -1))
						.isInstanceOf(RepositoryException.class)
						.hasMessageContaining("Illegal value for query timeout");
		storage.shutdown();
	}

	@Test
	void checkAccessAndShutdownHandleFailures() throws Exception {
		SailRepository accessibleRepository = new SailRepository(new MemoryStore());
		accessibleRepository.init();
		QueryStorage storage = new QueryStorage(accessibleRepository);
		Repository failingRepository = mock(Repository.class);

		when(failingRepository.getConnection()).thenThrow(new RepositoryException("denied"));

		assertThat(storage.checkAccess(accessibleRepository)).isTrue();
		assertThat(storage.checkAccess(failingRepository)).isFalse();

		Repository shutdownFailureRepository = mock(Repository.class);
		when(shutdownFailureRepository.isInitialized()).thenReturn(true);
		doThrow(new RepositoryException("boom")).when(shutdownFailureRepository).shutDown();

		new QueryStorage(shutdownFailureRepository).shutdown();
		storage.shutdown();
	}

	@Test
	void singletonReusesLiveStoreAndRecreatesAfterShutdown(@TempDir File dataDir) throws Exception {
		AppConfiguration config = mock(AppConfiguration.class);
		when(config.getDataDir()).thenReturn(dataDir);

		QueryStorage.getSingletonInstance(config).shutdown();

		QueryStorage first = QueryStorage.getSingletonInstance(config);
		QueryStorage second = QueryStorage.getSingletonInstance(config);
		assertThat(second).isSameAs(first);

		first.shutdown();

		QueryStorage recreated = QueryStorage.getSingletonInstance(config);
		assertThat(recreated).isNotSameAs(first);

		recreated.shutdown();
	}

